import sys
from collections import defaultdict, deque

def find_paths(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        queue = deque([(start, 0)])
        distances = [-1] * (n + 1)
        distances[start] = 0
        while queue:
            node, dist = queue.popleft()
            for neighbor in graph[node]:
                if distances[neighbor] == -1:
                    distances[neighbor] = dist + 1
                    queue.append((neighbor, dist + 1))
        return distances

    def lca(u, v, parents, depths):
        if depths[u] > depths[v]:
            u, v = v, u
        diff = depths[v] - depths[u]
        for i in range(17):
            if (diff >> i) & 1:
                v = parents[v][i]
        if u == v:
            return u
        for i in range(16, -1, -1):
            if parents[u][i] != parents[v][i]:
                u, v = parents[u][i], parents[v][i]
        return parents[u][0]

    def preprocess_lca():
        parents = [[-1] * 17 for _ in range(n + 1)]
        depths = [0] * (n + 1)
        stack = [(1, 0, -1)]
        while stack:
            node, depth, parent = stack.pop()
            depths[node] = depth
            parents[node][0] = parent
            for i in range(1, 17):
                if parents[node][i - 1] != -1:
                    parents[node][i] = parents[parents[node][i - 1]][i - 1]
            for neighbor in graph[node]:
                if neighbor != parent:
                    stack.append((neighbor, depth + 1, node))
        return parents, depths

    parents, depths = preprocess_lca()

    total_pairs = 0
    for a in range(1, n + 1):
        for b in range(a + 1, n + 1):
            la = lca(a, b, parents, depths)
            reachable_nodes = set()
            for node in range(1, n + 1):
                lb = lca(node, a, parents, depths)
                lc = lca(node, b, parents, depths)
                if lb != la and lc != la:
                    reachable_nodes.add(node)
            for c in range(a + 1, b):
                if c in reachable_nodes:
                    for d in range(c + 1, n + 1):
                        if d in reachable_nodes and lca(c, d, parents, depths) != la:
                            total_pairs += 1

    return total_pairs

input = sys.stdin.read().strip().split()
n = int(input[0])
edges = [(int(input[i * 2 + 1]), int(input[i * 2 + 2])) for i in range(n - 1)]
print(find_paths(n, edges))
